import{_ as a,o as e,c as i,a1 as n}from"./chunks/framework.DZA-Q4um.js";const k=JSON.parse('{"title":"Manjaro Black Screen Shows Only loadkmap short read, but the NVIDIA Kernel Module Is Missing","description":"Diagnose and restore a missing NVIDIA kernel module from a TTY when a Manjaro black screen shows only loadkmap short read.","frontmatter":{"title":"Manjaro Black Screen Shows Only loadkmap short read, but the NVIDIA Kernel Module Is Missing","description":"Diagnose and restore a missing NVIDIA kernel module from a TTY when a Manjaro black screen shows only loadkmap short read.","date":"2026-08-11T00:00:00.000Z","tags":["Manjaro","NVIDIA","KDE","Linux"],"sidebar":false},"headers":[],"relativePath":"blog/2026-08-11-manjaro-nvidia-black-screen.md","filePath":"blog/2026-08-11-manjaro-nvidia-black-screen.md"}'),t={name:"blog/2026-08-11-manjaro-nvidia-black-screen.md"};function l(h,s,p,o,d,r){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="manjaro-black-screen-shows-only-loadkmap-short-read-but-the-nvidia-kernel-module-is-missing" tabindex="-1">Manjaro Black Screen Shows Only <code>loadkmap: short read</code>, but the NVIDIA Kernel Module Is Missing <a class="header-anchor" href="#manjaro-black-screen-shows-only-loadkmap-short-read-but-the-nvidia-kernel-module-is-missing" aria-label="Permalink to &quot;Manjaro Black Screen Shows Only \`loadkmap: short read\`, but the NVIDIA Kernel Module Is Missing&quot;">​</a></h1><p><code>2026-08-11</code> · Manjaro · NVIDIA · KDE</p><p>After the computer froze and was forcibly rebooted, the system could no longer start KDE. The black screen showed only:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loadkmap: short read</span></span></code></pre></div><h2 id="check-sddm-from-a-tty" tabindex="-1">Check SDDM from a TTY <a class="header-anchor" href="#check-sddm-from-a-tty" aria-label="Permalink to &quot;Check SDDM from a TTY&quot;">​</a></h2><p>Press <code>Ctrl + Alt + F2</code> to enter a TTY, then inspect the SDDM status and logs from the current boot:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sddm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sddm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><p>The logs contained:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NVIDIA: Failed to initialize the NVIDIA kernel module</span></span>
<span class="line"><span>no screens found</span></span>
<span class="line"><span>Could not start Display server on vt 2</span></span></code></pre></div><p>This showed that SDDM could not start the graphical session because the NVIDIA kernel module failed to initialize. The <code>loadkmap</code> message visible on the screen was not the direct cause.</p><h2 id="confirm-that-the-nvidia-module-package-was-removed" tabindex="-1">Confirm That the NVIDIA Module Package Was Removed <a class="header-anchor" href="#confirm-that-the-nvidia-module-package-was-removed" aria-label="Permalink to &quot;Confirm That the NVIDIA Module Package Was Removed&quot;">​</a></h2><p>Next, search the pacman log:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;linux618-nvidia-open&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/pacman.log</span></span></code></pre></div><p>The log confirmed that an earlier orphan-package cleanup passed the full package-name list from <code>pacman -Qtdq</code> to <code>pacman -Rns</code>, removing <code>linux618-nvidia-open</code> along with the other packages. When the system next booted <code>linux618</code>, the matching NVIDIA module was unavailable, so KDE could not start.</p><p>A kernel package does not necessarily depend on the NVIDIA driver package, and pacman cannot determine whether an orphaned package is still required by the installed hardware. Never remove every package returned by an orphan query without reviewing the list.</p><h2 id="restore-the-system" tabindex="-1">Restore the System <a class="header-anchor" href="#restore-the-system" aria-label="Permalink to &quot;Restore the System&quot;">​</a></h2><p><code>linux618-nvidia-open</code> is the package used on this machine. On another system, first check the running kernel and installed NVIDIA module packages:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qq</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^linux[0-9]+($|-nvidia(-open)?$)&#39;</span></span></code></pre></div><p>After confirming the package name, the recommended recovery commands are:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux618-nvidia-open</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-keymap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkinitcpio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><p><code>localectl</code> is intentionally run without <code>sudo</code>. During this incident, <code>sudo localectl --no-convert set-keymap us</code> returned an error, while running the command directly succeeded. The full error was not saved, so this article does not speculate about the cause.</p><h2 id="commands-actually-used-during-this-incident" tabindex="-1">Commands Actually Used During This Incident <a class="header-anchor" href="#commands-actually-used-during-this-incident" aria-label="Permalink to &quot;Commands Actually Used During This Incident&quot;">​</a></h2><p>The TTY displayed the normal <code>sudo</code> password prompt, but after the password was entered, pressing Enter had no effect and the command never continued. As a temporary workaround, <code>sudo -S</code> was used to read the password from standard input:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;current user password&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pacman -Syu --noconfirm linux618-nvidia-open</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-keymap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;current user password&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mkinitcpio -P</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reboot</span></span></code></pre></div><p><code>sudo -S</code> reads the password from standard input.</p><p>After the reboot, the KDE desktop started normally.</p><h2 id="why-loadkmap-short-read-appeared" tabindex="-1">Why <code>loadkmap: short read</code> Appeared <a class="header-anchor" href="#why-loadkmap-short-read-appeared" aria-label="Permalink to &quot;Why \`loadkmap: short read\` Appeared&quot;">​</a></h2><p>The original <code>/etc/vconsole.conf</code> used a keymap that was unavailable on this machine:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KEYMAP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cn</span></span></code></pre></div><p>The following command changes it to the valid <code>us</code> keymap, and <code>mkinitcpio -P</code> then regenerates the initramfs:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-keymap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkinitcpio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span></span></code></pre></div><p>Therefore, <code>loadkmap: short read</code> was the only visible message on the black screen, but the missing NVIDIA module was what prevented KDE from starting. Both issues were fixed during the recovery.</p><h2 id="prevent-the-package-from-being-removed-again" tabindex="-1">Prevent the Package from Being Removed Again <a class="header-anchor" href="#prevent-the-package-from-being-removed-again" aria-label="Permalink to &quot;Prevent the Package from Being Removed Again&quot;">​</a></h2><p>Review orphaned packages individually before removing them:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qdt</span></span></code></pre></div><p>Do not pass the complete package-name list from <code>pacman -Qtdq</code> directly to <code>pacman -Rns</code> without reviewing it first. Pay particular attention to NVIDIA, headers, VirtualBox, and other modules associated with an installed kernel.</p><p>If a package that is still required is marked as orphaned, mark it as explicitly installed:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --asexplicit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux618-nvidia-open</span></span></code></pre></div><p>Reinstalling the package with <code>pacman -Syu linux618-nvidia-open</code>, as done here, also records it as explicitly installed.</p>`,39)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
